-- ============================================================================================
-- RECOMMANDATIONS : les champs chiffres de l'opportunite, et la vraie date de cloture
-- ============================================================================================
-- Deux manques signales par William le 15/08/2026, qui n'en font qu'un : « le montant n'est pas
-- affiche sur toutes les recos » et « recuperer les donnees des recommandations gagnees — date de
-- cloture, fournisseur, montant, marge, duree, budget de l'ancienne offre, difference budgetaire
-- annuelle, commission ».
--
-- CE QUE L'ON A CONSTATE. L'interface affiche bien le montant : c'est la donnee qui manquait.
-- Aucune des 2002 versions de recommandation ne porte de gain_estime_annuel, et la table
-- recommandations n'avait aucune colonne pour le montant, le fournisseur, la duree, les budgets
-- ni les commissions. Tout cela existe pourtant cote Salesforce, sur l'objet Opportunity.
--
-- LA DATE DE CLOTURE ETAIT FAUSSE, ET C'EST LE PLUS GRAVE. Les 1471 recommandations cloturees
-- portent TOUTES la meme date : 2026-08-03. La migration 20260812090000 les avait remplies avec
-- « coalesce(date_cloture, date_modification) », et date_modification valait la date de l'import,
-- pas celle de l'affaire. Impossible, aujourd'hui, de savoir quel jour une affaire a ete gagnee.
-- L'ecart median avec la vraie date Salesforce est de 265 jours, et va jusqu'a 937.
--
-- LE RAPPROCHEMENT. Les recommandations n'ont aucune tracabilite vers Salesforce : le lien se fait
-- donc sur le nom, apres normalisation (accents, casse, espaces). Mesure du 15/08/2026 :
--   1599 des 1703 recommandations appariees sans ambiguite
--    103 ecartees parce que leur nom existe en double d'un cote ou de l'autre
--      1 sans correspondance Salesforce
-- Les 103 ambigues ne sont PAS touchees : mieux vaut une donnee absente qu'une donnee attribuee au
-- mauvais dossier. Elles se traiteront quand les recommandations porteront un id_salesforce, ce
-- que cette migration commence a poser.
--
-- CE QUI N'EST PAS ECRASE. marge_brute et marge_nette sont deja renseignees sur 1471 et 1513
-- lignes par les imports precedents : on n'y touche pas. Seules les colonnes nouvelles sont
-- remplies, plus date_cloture dont on vient d'etablir qu'elle est fausse partout.
-- finalite_cloture est deja juste : 825 ACCEPTEE cote Kimatch, 825 gagnees cote Salesforce.
--
-- Chiffres portes par cette migration : 1599 montants, 1599 dates de cloture reelles,
-- 822 fournisseurs, 825 affaires gagnees.
-- ============================================================================================

begin;

-- --------------------------------------------------------------------------------------------
-- 1. Les colonnes qui manquaient
-- --------------------------------------------------------------------------------------------
alter table public.recommandations
  add column if not exists id_salesforce text,
  add column if not exists montant numeric,
  add column if not exists marge_nette_mwh numeric,
  add column if not exists duree_mois integer,
  add column if not exists volume_contractuel numeric,
  add column if not exists budget_ancienne_offre numeric,
  add column if not exists budget_nouvelle_offre numeric,
  add column if not exists difference_budgetaire numeric,
  add column if not exists difference_budgetaire_pourcentage numeric,
  add column if not exists commission_interne numeric,
  add column if not exists commission_nette numeric,
  add column if not exists remuneration_apporteur numeric,
  add column if not exists fournisseur_compte_id uuid references public.comptes(id);

comment on column public.recommandations.id_salesforce is
  'Identifiant Salesforce de l''opportunite d''origine. Pose le 15/08/2026 pour que les reprises suivantes n''aient plus a rapprocher par le nom.';
comment on column public.recommandations.montant is
  'Opportunity.Montant__c — le montant de l''affaire, affiche sur la fiche recommandation.';
comment on column public.recommandations.difference_budgetaire is
  'Opportunity.Difference_budgetaire__c — ecart annuel entre l''ancienne et la nouvelle offre.';

create index if not exists idx_recommandations_id_salesforce
  on public.recommandations (id_salesforce) where id_salesforce is not null;

-- --------------------------------------------------------------------------------------------
-- 2. Les valeurs, reprises de Salesforce
-- --------------------------------------------------------------------------------------------
with valeurs (reco_id, sf_id, montant, marge_nette_mwh, duree_mois, volume, budget_ancien,
              budget_nouveau, diff_budget, diff_budget_pct, commission_interne, commission_nette,
