update public.recommandations r set
  id_salesforce                     = v.sf_id,
  montant                           = v.montant,
  marge_nette_mwh                   = v.marge_nette_mwh,
  duree_mois                        = v.duree_mois,
  volume_contractuel                = v.volume,
  budget_ancienne_offre             = v.budget_ancien,
  budget_nouvelle_offre             = v.budget_nouveau,
  difference_budgetaire             = v.diff_budget,
  difference_budgetaire_pourcentage = v.diff_budget_pct,
  commission_interne                = v.commission_interne,
  commission_nette                  = v.commission_nette,
  remuneration_apporteur            = v.remuneration_ap,
  fournisseur_compte_id             = v.fournisseur_id,
  -- La date de cloture est reecrite sans condition : celle qui s'y trouve est la date de l'import.
  date_cloture                      = coalesce(v.close_date, r.date_cloture),
  -- L'energie n'etait renseignee que sur 10 des 1599 lignes ; l'emoji du nom la donne.
  type_energie_id                   = coalesce(r.type_energie_id, v.energie_id),
  date_modification                 = now()
from valeurs v
where r.id = v.reco_id;

commit;

-- ============================================================================================
-- CONTROLE APRES APPLICATION
-- ============================================================================================
--   select count(*) total,
--          count(montant) avec_montant,
--          count(fournisseur_compte_id) avec_fournisseur,
--          count(distinct date_cloture) dates_distinctes
--   from recommandations where id_salesforce is not null;
--
-- Attendu : 1599 lignes, 1599 montants, 822 fournisseurs, et surtout un nombre
-- de dates distinctes tres superieur a 1 — c'etait la tout le probleme.
